package com.andye.warmod.phalanx;import java.util.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.ChunkPos;public final class PhalanxChunkTicketManager{private static final Map<ServerLevel,Map<UUID,Set<ChunkPos>>> ACTIVE=new WeakHashMap<>();private PhalanxChunkTicketManager(){}public static synchronized boolean register(ServerLevel l,UUID id,net.minecraft.core.BlockPos p){var m=ACTIVE.computeIfAbsent(l,x->new LinkedHashMap<>());if(!m.containsKey(id)&&m.size()>=PhalanxConstants.MAX_TURRETS_PER_LEVEL)return false;Set<ChunkPos> chunks=Set.of(new ChunkPos(p.getX()>>4,p.getZ()>>4),new ChunkPos((p.getX()+1)>>4,p.getZ()>>4),new ChunkPos(p.getX()>>4,(p.getZ()+1)>>4),new ChunkPos((p.getX()+1)>>4,(p.getZ()+1)>>4));for(var c:chunks)l.getChunkSource().addTicketWithRadius(PhalanxChunkTicketType.TURRET,c,0);m.put(id,chunks);return true;}public static synchronized void unregister(ServerLevel l,UUID id){var m=ACTIVE.get(l);if(m==null)return;var chunks=m.remove(id);if(chunks!=null)for(var c:chunks)l.getChunkSource().removeTicketWithRadius(PhalanxChunkTicketType.TURRET,c,0);if(m.isEmpty())ACTIVE.remove(l);}public static synchronized void clear(){for(var e:ACTIVE.entrySet())for(var chunks:e.getValue().values())for(var c:chunks)e.getKey().getChunkSource().removeTicketWithRadius(PhalanxChunkTicketType.TURRET,c,0);ACTIVE.clear();}}
